    ]
  },
  "dual_mode_assessment": {
    "status": "acceptable",
    "notes": [
      "Local and AWS modes preserve the same business flow, UI behavior, and POST /documents contract.",
      "Runtime differences are expressed through environment-configured base URL and profile header, which is the right direction.",
      "Dual-mode integrity is undermined only by lack of tests against the real adapter behavior; the design itself remains coherent."
    ]
  },
  "blockers": [
